    function loadState() {
        const saved = localStorage.getItem('win2026_state');
        if (!saved) return false;
        try {
            const state = JSON.parse(saved);
            deletedApps = state.deletedApps || [];
            deletedDownloadedGames = state.deletedDownloadedGames || [];
            customFolders = state.customFolders || [];
            desktopFiles = state.desktopFiles || [];
            appPositions = state.appPositions || {};
            officeProjects = state.officeProjects || [];
            desktopBgColor = state.desktopBgColor || "#1b4d2e";
            wallpaperUrl = state.wallpaperUrl || null;
            wallpaperDataURL = state.wallpaperDataURL || null;
            taskbarAutoHide = state.taskbarAutoHide || false;
            iconSize = state.iconSize || 80;
            iconSpacing = state.iconSpacing || 100;
            taskbarHeight = state.taskbarHeight || 48;
            fontSize = state.fontSize || 13;
            borderRadius = state.borderRadius || 12;
            animations = state.animations !== undefined ? state.animations : true;
            accentColor = state.accentColor || "#2c5a3e";
            taskbarTransparency = state.taskbarTransparency !== undefined ? state.taskbarTransparency : 0.92;
            showHiddenFiles = state.showHiddenFiles || false;
            doubleClickSpeed = state.doubleClickSpeed || 500;
            windowOpacity = state.windowOpacity !== undefined ? state.windowOpacity : 1;
            mouseStyle = state.mouseStyle || "default";
            startupSoundEnabled = state.startupSoundEnabled !== undefined ? state.startupSoundEnabled : true;
            showWelcomeScreen = state.showWelcomeScreen !== undefined ? state.showWelcomeScreen : true;
            windowSnap = state.windowSnap !== undefined ? state.windowSnap : true;
            iconTextShadow = state.iconTextShadow !== undefined ? state.iconTextShadow : true;
            iconDragMode = state.iconDragMode || 'grid';
            iconLabelTransparency = state.iconLabelTransparency !== undefined ? state.iconLabelTransparency : 0.3;
            showIconLabels = state.showIconLabels !== undefined ? state.showIconLabels : true;
            clockFormat = state.clockFormat || '12h';
            customAppIcons = state.customAppIcons || {};
            downloadedGames = (state.downloadedGames || []).map(g => {
                if (g.id === 'pinterest') return { id: g.id, name: g.name, icon: g.icon, launch: () => { openPinterestApp(); } };
                else if (g.id === 'chrome') return { id: g.id, name: g.name, icon: g.icon, launch: () => { openChromeApp(); } };
                else if (g.id === 'bank') return { id: g.id, name: g.name, icon: g.icon, launch: () => { openBankApp(); } };
                else if (g.id === 'discord') return { id: g.id, name: g.name, icon: g.icon, launch: () => { openInAppBrowser('https://krisxxxllkrisipurvanov-cpu.github.io/Discord/', 'Discord'); } };
                else if (g.id === 'microsoftplus') return { id: g.id, name: g.name, icon: g.icon, launch: () => { openInAppBrowser('https://krisxxxllkrisipurvanov-cpu.github.io/MicrosoftPlus/', 'Microsoft+'); } };
                else if (g.id === 'sky_parkour') return { id: g.id, name: g.name, icon: g.icon, launch: () => { openInAppBrowser('https://krisxxxllkrisipurvanov-cpu.github.io/3D-GAME/', 'Sky Parkour'); } };
                else if (g.id === 'youtube') return { id: g.id, name: g.name, icon: g.icon, launch: () => { openInAppBrowser('https://krisxxxllkrisipurvanov-cpu.github.io/Maze/', 'YouTube'); } };
                else if (g.id === 'smartybox') return { id: g.id, name: g.name, icon: g.icon, launch: () => { openInAppBrowser('https://krisxxxllkrisipurvanov-cpu.github.io/Smatrybox/', 'Smartybox'); } };
                return null;
            }).filter(g => g);
            window.__pinnedApps = state.pinnedApps || [];
            window.__savedWorkspaces = state.workspaces || null;
            window.__savedActiveWorkspace = state.activeWorkspace || 0;
            window.__lockPassword = state.lockPassword || "";
            applyWallpaper();
            applyAccentAndTaskbar();
            applyExtraSettings();
            return true;
        } catch(e) { console.warn("Failed to load state", e); return false; }
    }

    function applyExtraSettings() {
        document.body.style.cursor = mouseStyle;
        document.querySelectorAll('.app-window').forEach(win => { win.style.opacity = windowOpacity; });
        document.querySelectorAll('.desktop-icon span').forEach(span => {
            span.style.textShadow = iconTextShadow ? '0 1px 2px black' : 'none';
            span.style.display = showIconLabels ? 'block' : 'none';
        });
        document.querySelectorAll('.desktop-icon').forEach(icon => {
            icon.style.background = `rgba(0,0,0,${iconLabelTransparency})`;
        });
        updateClock();
    }

