    // --- WALLPAPER & ACCENT ---
    function applyWallpaper() {
        if (wallpaperUrl) {
            desktopDiv.style.backgroundImage = `url(${wallpaperUrl})`;
            desktopDiv.style.backgroundColor = "transparent";
        } else if (wallpaperDataURL) {
            desktopDiv.style.backgroundImage = `url(${wallpaperDataURL})`;
            desktopDiv.style.backgroundColor = "transparent";
        } else {
            desktopDiv.style.backgroundImage = "none";
            desktopDiv.style.backgroundColor = desktopBgColor;
        }
    }
    function applyAccentAndTaskbar() {
        document.querySelectorAll('.app-window .window-header').forEach(header => {
            header.style.background = `linear-gradient(90deg, ${accentColor}, ${adjustColor(accentColor, -20)})`;
        });
        taskbar.style.backgroundColor = `rgba(30, 40, 50, ${taskbarTransparency})`;
        taskbar.style.backdropFilter = `blur(${12 * taskbarTransparency}px)`;
    }
    function adjustColor(color, percent) {
        let R = parseInt(color.substring(1,3), 16), G = parseInt(color.substring(3,5), 16), B = parseInt(color.substring(5,7), 16);
        R = Math.min(255, Math.max(0, R + percent));
        G = Math.min(255, Math.max(0, G + percent));
        B = Math.min(255, Math.max(0, B + percent));
        return `rgb(${R}, ${G}, ${B})`;
    }

    // --- INTERNET & CLOCK ---
    function updateInternetStatus() {
        let ping = Math.floor(Math.random() * 112) + 8;
        let q = ping<=20?"Excellent":ping<=50?"Good":ping<=80?"Fair":"Slow";
        const bars = ping<=20 ? 4 : ping<=50 ? 3 : ping<=80 ? 2 : 1;
        let connected = true; try { connected = trayState ? trayState.wifi !== false : true; } catch(e) {}
        const col = connected ? 'white' : '#888';
        const txtEl = document.getElementById('internetStatusText');
        const icoEl = document.getElementById('internetStatusIcon');
        if (txtEl) { txtEl.textContent = ''; txtEl.style.display = 'none'; }
        if (icoEl) icoEl.innerHTML = [
            `<rect x="1"  y="17" width="4" height="6"  rx="1" fill="${bars>=1 && connected ? col : 'rgba(255,255,255,0.25)'}"/>`,
            `<rect x="7"  y="12" width="4" height="11" rx="1" fill="${bars>=2 && connected ? col : 'rgba(255,255,255,0.25)'}"/>`,
            `<rect x="13" y="7"  width="4" height="16" rx="1" fill="${bars>=3 && connected ? col : 'rgba(255,255,255,0.25)'}"/>`,
            `<rect x="19" y="2"  width="4" height="21" rx="1" fill="${bars>=4 && connected ? col : 'rgba(255,255,255,0.25)'}"  />`
        ].join('');
    }
    setInterval(updateInternetStatus, 3000); updateInternetStatus();
    function updateClock() { 
        let d = new Date(); 
        let timeStr = clockFormat === '12h' ? d.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : d.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit', hour12: false});
        let dateStr = d.toLocaleDateString([], {month:'numeric', day:'numeric', year:'numeric'});
        document.getElementById('clockTime').textContent = timeStr;
        document.getElementById('clockDate').textContent = dateStr;
        // Update panel big clock if open
        const bigTime = document.getElementById('calBigTime');
        if(bigTime) bigTime.textContent = timeStr;
    }
    setInterval(updateClock, 1000); updateClock();

    // ===== WIN11 CALENDAR PANEL =====
    (function() {
        // Inject panel into DOM
        const panel = document.createElement('div');
        panel.className = 'win11-cal-panel';
        panel.id = 'win11CalPanel';
        panel.innerHTML = `
            <div class="cal-top">
                <div class="cal-big-time" id="calBigTime"></div>
                <div class="cal-big-date" id="calBigDate"></div>
            </div>
            <div class="cal-month-nav">
                <span class="cal-month-label" id="calMonthLabel"></span>
                <div style="display:flex;gap:4px;">
                    <button class="cal-nav-btn" id="calPrev">&#8249;</button>
                    <button class="cal-nav-btn" id="calNext">&#8250;</button>
                </div>
            </div>
            <div class="cal-grid" id="calGrid"></div>
            <div class="cal-panel-footer">
                <button class="cal-footer-btn" id="calTodayBtn">📅 Go to today</button>
                <button class="cal-footer-btn" id="calOpenSettings">⚙️ Date &amp; time settings</button>
            </div>`;
        document.body.appendChild(panel);

        const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
        const DAYS = ['Su','Mo','Tu','We','Th','Fr','Sa'];
        let calYear, calMonth;

        function renderCalendar() {
            const now = new Date();
            const label = document.getElementById('calMonthLabel');
            const grid = document.getElementById('calGrid');
            if(label) label.textContent = MONTHS[calMonth] + ' ' + calYear;

            // Build grid: day-of-week headers
            grid.innerHTML = DAYS.map(d=>`<div class="cal-dow">${d}</div>`).join('');

            const first = new Date(calYear, calMonth, 1).getDay();
            const daysInMonth = new Date(calYear, calMonth+1, 0).getDate();
            const daysInPrev = new Date(calYear, calMonth, 0).getDate();

            // Prev month tail
            for(let i=first-1; i>=0; i--) {
                grid.innerHTML += `<div class="cal-day other-month">${daysInPrev-i}</div>`;
            }
            // Current month
            for(let d=1; d<=daysInMonth; d++) {
                const isToday = d===now.getDate() && calMonth===now.getMonth() && calYear===now.getFullYear();
                grid.innerHTML += `<div class="cal-day${isToday?' today':''}">${d}</div>`;
            }
            // Next month fill
            const total = first + daysInMonth;
            const remainder = total % 7 === 0 ? 0 : 7 - (total % 7);
            for(let d=1; d<=remainder; d++) {
                grid.innerHTML += `<div class="cal-day other-month">${d}</div>`;
            }

            // Big date
            const bigDate = document.getElementById('calBigDate');
            const bigTime = document.getElementById('calBigTime');
            const nd = new Date();
            if(bigDate) bigDate.textContent = nd.toLocaleDateString([], {weekday:'long', month:'long', day:'numeric', year:'numeric'});
            if(bigTime) {
                let t = clockFormat === '12h' ? nd.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) : nd.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false});
                bigTime.textContent = t;
            }
        }

        function openPanel() {
            const now = new Date();
            calYear = now.getFullYear(); calMonth = now.getMonth();
            renderCalendar();
            panel.classList.add('show');
        }
        function closePanel() { panel.classList.remove('show'); }

        document.getElementById('clock').addEventListener('click', e => {
            e.stopPropagation();
            panel.classList.contains('show') ? closePanel() : openPanel();
        });
        document.getElementById('calPrev').addEventListener('click', e => {
            e.stopPropagation();
            calMonth--; if(calMonth<0){calMonth=11;calYear--;} renderCalendar();
        });
        document.getElementById('calNext').addEventListener('click', e => {
            e.stopPropagation();
            calMonth++; if(calMonth>11){calMonth=0;calYear++;} renderCalendar();
        });
        document.getElementById('calTodayBtn').addEventListener('click', e => {
            e.stopPropagation();
            const now = new Date(); calYear=now.getFullYear(); calMonth=now.getMonth(); renderCalendar();
        });
        document.getElementById('calOpenSettings').addEventListener('click', e => {
            e.stopPropagation();
            closePanel();
            if(typeof openSettings === 'function') openSettings('system');
            else { /* fallback: open settings */ const sBtn = document.getElementById('settingsBtn'); if(sBtn) sBtn.click(); }
        });
        document.addEventListener('click', e => {
            if(!panel.contains(e.target) && e.target.id !== 'clock' && !e.target.closest('#clock')) closePanel();
        });
        panel.addEventListener('click', e => e.stopPropagation());
    })();

    // --- TASKBAR BUTTONS ---
    // === Window animation helpers (Win11-style) ===
    let __launchSourceRect = null;
    function captureLaunchSource(e) {
        try {
            const el = e && (e.currentTarget || e.target);
            if (el && el.getBoundingClientRect) __launchSourceRect = el.getBoundingClientRect();
        } catch(_) { __launchSourceRect = null; }
        // auto-clear shortly after so it doesn't leak to unrelated calls
        setTimeout(() => { __launchSourceRect = null; }, 50);
    }
    document.addEventListener('mousedown', (e) => {
        const src = e.target.closest('.desktop-icon, .start-items li, .taskbar-app-btn, .start-button');
        if (src) __launchSourceRect = src.getBoundingClientRect();
    }, true);

    function getTaskbarBtnRect(winId) {
        const btn = taskbarItemsDiv.querySelector(`[data-winid="${CSS.escape(winId)}"]`);
        return btn ? btn.getBoundingClientRect() : null;
    }
    function setMinimizeVars(w, targetRect) {
        const r = w.getBoundingClientRect();
        if (!targetRect) targetRect = { left: r.left + r.width/2, top: window.innerHeight - 24, width: 0, height: 0 };
        const dx = (targetRect.left + targetRect.width/2) - (r.left + r.width/2);
        const dy = (targetRect.top + targetRect.height/2) - (r.top + r.height/2);
        // because transform scales 0.25, divide translate by 0.25 to land on target
        w.style.setProperty('--mx', (dx / 0.25) + 'px');
        w.style.setProperty('--my', (dy / 0.25) + 'px');
    }
    function setOpenOrigin(w, sourceRect) {
        const r = w.getBoundingClientRect();
        if (!sourceRect) { w.style.setProperty('--tx','50%'); w.style.setProperty('--ty','100%'); return; }
        const ox = ((sourceRect.left + sourceRect.width/2) - r.left);
        const oy = ((sourceRect.top + sourceRect.height/2) - r.top);
        w.style.setProperty('--tx', ox + 'px');
        w.style.setProperty('--ty', oy + 'px');
    }

    function makeDraggable(h, w) {
        let ox, oy, drag = false, startX = 0, startY = 0, snapZone = null;
        const snapPreview = (() => {
            let p = document.getElementById('__snapPreview');
            if (!p) { p = document.createElement('div'); p.id = '__snapPreview'; p.className = 'snap-preview'; document.body.appendChild(p); }
            return p;
        })();
        function computeZone(x, y) {
            if (!windowSnap) return null;
            const tb = taskbarHeight || 48;
            if (y < 8) return { left: 0, top: 0, width: window.innerWidth, height: window.innerHeight - tb, kind: 'max' };
            if (x < 8) return { left: 0, top: 0, width: window.innerWidth/2, height: window.innerHeight - tb, kind: 'left' };
            if (x > window.innerWidth - 8) return { left: window.innerWidth/2, top: 0, width: window.innerWidth/2, height: window.innerHeight - tb, kind: 'right' };
            return null;
        }
        h.addEventListener('mousedown', (e) => {
            if (e.target.closest('.window-controls')) return;
            if (w.classList.contains('maximized')) return; // don't drag while maximized
            drag = true; ox = e.clientX - w.offsetLeft; oy = e.clientY - w.offsetTop; startX = e.clientX; startY = e.clientY;
            w.style.zIndex = Date.now();
            w.classList.add('dragging');
            document.addEventListener('mousemove', move);
            document.addEventListener('mouseup', up);
            e.preventDefault();
        });
        function move(e) {
            if (!drag) return;
            let l = e.clientX - ox, t = e.clientY - oy;
            l = Math.min(Math.max(l, 0), window.innerWidth - w.offsetWidth);
            t = Math.min(Math.max(t, 0), window.innerHeight - 70);
            w.style.left = l + 'px'; w.style.top = t + 'px';
            const zone = computeZone(e.clientX, e.clientY);
            snapZone = zone;
            if (zone) {
                snapPreview.style.left = zone.left + 'px';
                snapPreview.style.top = zone.top + 'px';
                snapPreview.style.width = zone.width + 'px';
                snapPreview.style.height = zone.height + 'px';
                snapPreview.classList.add('show');
            } else {
                snapPreview.classList.remove('show');
            }
        }
        function up() {
            drag = false;
            w.classList.remove('dragging');
            snapPreview.classList.remove('show');
            if (snapZone && animations) {
                if (snapZone.kind === 'max') { maximizeWindow(w); }
                else { snapToZone(w, snapZone); }
            }
            snapZone = null;
            document.removeEventListener('mousemove', move);
            document.removeEventListener('mouseup', up);
        }
    }

    function snapToZone(w, zone) {
        if (!w.dataset.prevBounds) {
            w.dataset.prevBounds = JSON.stringify({ left: w.style.left, top: w.style.top, width: w.style.width || w.offsetWidth+'px', height: w.style.height || w.offsetHeight+'px' });
        }
        w.classList.add('snapping');
        w.style.left = zone.left + 'px';
        w.style.top = zone.top + 'px';
        w.style.width = zone.width + 'px';
        w.style.height = zone.height + 'px';
        setTimeout(() => w.classList.remove('snapping'), 220);
    }
    function maximizeWindow(w) {
        if (w.classList.contains('maximized')) return;
        w.dataset.prevBounds = JSON.stringify({ left: w.style.left, top: w.style.top, width: w.style.width || w.offsetWidth+'px', height: w.style.height || w.offsetHeight+'px' });
        w.classList.add('maximized', 'snapping');
        w.style.left = '0px'; w.style.top = '0px';
        w.style.width = window.innerWidth + 'px';
        w.style.height = (window.innerHeight - (taskbarHeight || 48)) + 'px';
        setTimeout(() => w.classList.remove('snapping'), 220);
    }
    function restoreWindow(w) {
        if (!w.dataset.prevBounds) { w.classList.remove('maximized'); return; }
        const b = JSON.parse(w.dataset.prevBounds);
        w.classList.add('snapping');
        w.classList.remove('maximized');
        w.style.left = b.left || '100px';
        w.style.top = b.top || '80px';
        w.style.width = b.width || '550px';
        w.style.height = b.height || '500px';
        delete w.dataset.prevBounds;
        setTimeout(() => w.classList.remove('snapping'), 220);
    }
    function toggleMaximize(w) {
        if (w.classList.contains('maximized')) restoreWindow(w); else maximizeWindow(w);
    }

    function updateTaskbarButtons() {
        taskbarItemsDiv.innerHTML = '';
        for (let [winId, info] of openWindows.entries()) {
            let btn = document.createElement('div');
            btn.className = 'taskbar-app-btn';
            btn.setAttribute('data-winid', winId);
            btn.innerHTML = `${info.icon} ${info.title}`;
            if (info.windowElement.style.display !== 'none') btn.classList.add('active');
            btn.onclick = () => {
                const w = info.windowElement;
                if (w.style.display === 'none') {
                    // Restore from minimized: animate from taskbar btn back to window
                    setMinimizeVars(w, btn.getBoundingClientRect());
                    w.style.display = 'flex';
                    if (animations) {
                        w.classList.remove('minimizing');
                        w.classList.add('restoring');
                        w.addEventListener('animationend', function h() { w.classList.remove('restoring'); w.removeEventListener('animationend', h); });
                    }
                    w.style.zIndex = Date.now();
                    btn.classList.add('active');
                } else {
                    // Already open: minimize it
                    minimizeWindow(w, winId);
                }
            };
            taskbarItemsDiv.appendChild(btn);
        }
    }

    function minimizeWindow(w, winId) {
        const btnRect = getTaskbarBtnRect(winId);
        setMinimizeVars(w, btnRect);
        if (!animations) { w.style.display = 'none'; updateTaskbarButtons(); return; }
        w.classList.remove('opening', 'restoring');
        w.classList.add('minimizing');
        w.addEventListener('animationend', function h() {
            w.classList.remove('minimizing');
            w.style.display = 'none';
            w.removeEventListener('animationend', h);
            updateTaskbarButtons();
        });
    }

    function bringToFront(win) { win.style.zIndex = Date.now(); if (win.style.display === 'none') win.style.display = 'flex'; }

    function registerWindow(appId, win, title, icon) {
        // Use appId directly as the window key so callers can do openWindows.has(appId)
        // to detect/focus an already-open singleton window. Only add a suffix if a
        // window with that key is already registered (defensive — should be rare).
        let id = appId;
        if (openWindows.has(id)) id = appId + '_' + Date.now();
        openWindows.set(id, { windowElement: win, title, icon });
        updateTaskbarButtons();
        // Bounce the new taskbar button to signal launch
        const btn = taskbarItemsDiv.querySelector(`[data-winid="${CSS.escape(id)}"]`);
        if (btn && animations) { btn.classList.add('launching'); setTimeout(() => btn.classList.remove('launching'), 1200); }
        win.addEventListener('mousedown', () => win.style.zIndex = Date.now());
        // Close with animation
        win.querySelector('.close-win').onclick = () => {
            if (!animations) { win.remove(); openWindows.delete(id); updateTaskbarButtons(); return; }
            win.classList.remove('opening');
            win.classList.add('closing');
            win.addEventListener('animationend', function h() {
                win.removeEventListener('animationend', h);
                win.remove();
                openWindows.delete(id);
                updateTaskbarButtons();
            });
        };
        // Minimize with animation toward taskbar
        win.querySelector('.minimize').onclick = () => minimizeWindow(win, id);
        // Maximize/restore button (added in createWindow)
        const maxBtn = win.querySelector('.maximize');
        if (maxBtn) maxBtn.onclick = () => toggleMaximize(win);
        // Double-click header toggles maximize
        const header = win.querySelector('.window-header');
        if (header) header.addEventListener('dblclick', (e) => { if (!e.target.closest('.window-controls')) toggleMaximize(win); });
        return id;
    }

    function createWindow(title, html, appId) {
        let w = document.createElement('div');
        w.className = 'app-window';
        w.style.left = '100px'; w.style.top = '80px'; w.style.zIndex = Date.now();
        w.style.borderRadius = borderRadius + 'px'; w.style.opacity = windowOpacity;
        w.innerHTML = `<div class="window-header" style="border-radius:${borderRadius}px ${borderRadius}px 0 0; background: linear-gradient(90deg, ${accentColor}, ${adjustColor(accentColor, -20)});"><span>${title}</span><div class="window-controls"><span class="minimize" title="Minimize"><svg viewBox="0 0 10 10" xmlns="http://www.w3.org/2000/svg" width="10" height="10"><rect x="0" y="4.5" width="10" height="1" fill="white"/></svg></span><span class="maximize" title="Maximize"><svg viewBox="0 0 10 10" xmlns="http://www.w3.org/2000/svg" width="10" height="10"><rect x="0.75" y="0.75" width="8.5" height="8.5" fill="none" stroke="white" stroke-width="1"/></svg></span><span class="close-win" title="Close"><svg viewBox="0 0 10 10" xmlns="http://www.w3.org/2000/svg" width="10" height="10"><line x1="0.5" y1="0.5" x2="9.5" y2="9.5" stroke="white" stroke-width="1.1" stroke-linecap="round"/><line x1="9.5" y1="0.5" x2="0.5" y2="9.5" stroke="white" stroke-width="1.1" stroke-linecap="round"/></svg></span></div></div><div class="window-content">${html}</div>`;
        makeDraggable(w.querySelector('.window-header'), w);
        // Use real app icon URL from APP_LIST; fall back to a clean SVG for unknown apps
        const __appEntry = APP_LIST.find(a => a.id === appId);
        let icon = (__appEntry && typeof __appEntry.icon === 'string' && __appEntry.icon.startsWith('http'))
            ? `<img src="${__appEntry.icon}" style="width:18px;height:18px;object-fit:contain;vertical-align:middle;border-radius:3px;" alt="">`
            : ({
                cmd: `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" style="vertical-align:middle;"><rect width="24" height="24" rx="4" fill="#1a1a2e"/><text x="3" y="16" font-family="monospace" font-size="11" fill="#4ade80">&gt;_</text></svg>`,
              }[appId] || `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:middle;"><rect x="3" y="3" width="18" height="18" rx="2"/></svg>`);
        registerWindow(appId, w, title, icon);
        // Open animation: scale up from the launching source if known
        if (animations) {
            // defer to after element is in DOM (callers append after createWindow)
            requestAnimationFrame(() => {
                requestAnimationFrame(() => {
                    setOpenOrigin(w, __launchSourceRect);
                    w.classList.add('opening');
                    w.addEventListener('animationend', function h() { w.classList.remove('opening'); w.removeEventListener('animationend', h); });
                });
            });
        } else {
            w.style.transition = 'none';
        }
        return w;
    }


    // --- DESKTOP ICONS & POSITIONING ---
    function isInAnyFolder(kind, id) { let key = kind==='game' ? `game_${id}` : id; for(let f of customFolders) { if((f.contents||[]).includes(String(key)) || (f.contents||[]).includes(key)) return true; } return false; }
    function getNextFreePosition() { let taken = []; for(let a of APP_LIST.filter(a=>a.desktop && !deletedApps.includes(a.id) && !isInAnyFolder('app',a.id))) { let p = appPositions[a.id]; if(p) taken.push(`${p.x},${p.y}`); } for(let f of customFolders) taken.push(`${f.x},${f.y}`); for(let f of desktopFiles) taken.push(`${f.x},${f.y}`); for(let g of downloadedGames) if(!deletedDownloadedGames.includes(g.id) && !isInAnyFolder('game',g.id)) { let p = appPositions[`game_${g.id}`]; if(p) taken.push(`${p.x},${p.y}`); } for(let i=0;i<100;i++){ let x=20+(i%5)*iconSpacing, y=20+Math.floor(i/5)*iconSpacing; if(!taken.includes(`${x},${y}`)) return {x,y}; } return {x:20,y:20}; }
    function autoArrangeIcons() { let idx=0; let items = []; for(let a of APP_LIST.filter(a=>a.desktop && !deletedApps.includes(a.id) && !isInAnyFolder('app',a.id))) items.push({type:'app',id:a.id}); for(let f of customFolders) items.push({type:'folder',id:f.id}); for(let f of desktopFiles) items.push({type:'file',id:f.id}); for(let g of downloadedGames) if(!deletedDownloadedGames.includes(g.id) && !isInAnyFolder('game',g.id)) items.push({type:'game',id:g.id}); for(let it of items) { let x=20+(idx%5)*iconSpacing, y=20+Math.floor(idx/5)*iconSpacing; if(it.type==='app') appPositions[it.id]={x,y}; else if(it.type==='folder') { let f=customFolders.find(f=>f.id==it.id); if(f) { f.x=x; f.y=y; } } else if(it.type==='file') { let f=desktopFiles.find(f=>f.id==it.id); if(f) { f.x=x; f.y=y; } } else if(it.type==='game') appPositions[`game_${it.id}`]={x,y}; idx++; } renderDesktopIcons(); }
    function renderDesktopIcons() { desktopIconsContainer.innerHTML = ''; for(let a of APP_LIST.filter(a=>a.desktop && !deletedApps.includes(a.id) && !isInAnyFolder('app',a.id))) { let p=appPositions[a.id]||getNextFreePosition(); appPositions[a.id]=p; let iconSrc = customAppIcons[a.id] || a.icon; desktopIconsContainer.appendChild(createIcon('app',a.id,iconSrc,a.name,p.x,p.y)); } for(let f of customFolders) desktopIconsContainer.appendChild(createIcon('folder',f.id,'📁',f.name,f.x,f.y)); for(let f of desktopFiles) desktopIconsContainer.appendChild(createIcon('file',f.id,'📄',f.name,f.x,f.y)); for(let g of downloadedGames) if(!deletedDownloadedGames.includes(g.id) && !isInAnyFolder('game',g.id)) { let p=appPositions[`game_${g.id}`]||getNextFreePosition(); appPositions[`game_${g.id}`]=p; desktopIconsContainer.appendChild(createIcon('game',g.id,g.icon,g.name,p.x,p.y)); } let rp=appPositions['recycleBin']||{x:20,y:400}; appPositions['recycleBin']=rp; let rec=createIcon('app','recycleBin',APP_LIST.find(a=>a.id==='recycleBin').icon,'Recycle Bin',rp.x,rp.y); rec.addEventListener('dragover',e=>e.preventDefault()); rec.addEventListener('drop',handleDropOnRecycleBin); desktopIconsContainer.appendChild(rec); applyDesktopSettings(); saveState(); }
    function createIcon(type,id,iconChar,label,left,top) {
        let d=document.createElement('div');
        d.className='desktop-icon';
        d.setAttribute('data-type',type);
        d.setAttribute('data-id',id);
        d.style.left=left+'px'; d.style.top=top+'px'; d.style.width=iconSize+'px';
        d.style.background = `rgba(0,0,0,${iconLabelTransparency})`;
        d.style.backdropFilter = 'none';
        let iconHtml = iconChar.startsWith('http') ? `<img src="${iconChar}" alt="${label}" style="width:42px; height:42px; object-fit:contain;">` : `<div style="font-size:42px;">${iconChar}</div>`;
        d.innerHTML = `${iconHtml}<span style="font-size:${fontSize}px; display:${showIconLabels?'block':'none'}">${label}</span>`;
        d.addEventListener('mousedown',startDrag);
        if(type==='app') d.addEventListener('dblclick',()=>launchApp(id));
        else if(type==='folder') d.addEventListener('dblclick',()=>openFolder(id));
        else if(type==='file') d.addEventListener('dblclick',()=>openFile(id));
        else if(type==='game') d.addEventListener('dblclick',()=>{ let g=downloadedGames.find(g=>g.id==id); if(g&&g.launch) g.launch(); });
        return d;
    }
    function startDrag(e) { let ic=e.target.closest('.desktop-icon'); if(!ic) return; e.preventDefault(); dragTarget=ic; let r=ic.getBoundingClientRect(); dragOffsetX=e.clientX-r.left; dragOffsetY=e.clientY-r.top; dragStartX=e.clientX; dragStartY=e.clientY; dragOrigLeft=parseFloat(ic.style.left)||0; dragOrigTop=parseFloat(ic.style.top)||0; isDraggingForMove=false; ic.classList.add('dragging'); document.addEventListener('mousemove',onDragMove); document.addEventListener('mouseup',stopDrag); }
    function onDragMove(e) {
        if(!dragTarget) return;
        let dx=Math.abs(e.clientX-dragStartX), dy=Math.abs(e.clientY-dragStartY);
        if(!isDraggingForMove && (dx>5||dy>5)) isDraggingForMove=true;
        if(isDraggingForMove) {
            let l=e.clientX-dragOffsetX, t=e.clientY-dragOffsetY;
            l=Math.min(Math.max(l,0),window.innerWidth-dragTarget.offsetWidth);
            t=Math.min(Math.max(t,0),window.innerHeight-70);
            if(iconDragMode === 'grid') {
                const gs = iconSpacing, ox = 20, oy = 20;
                l = ox + Math.round((l - ox) / gs) * gs;
                t = oy + Math.round((t - oy) / gs) * gs;
                l = Math.min(Math.max(l, ox), window.innerWidth - dragTarget.offsetWidth);
                t = Math.min(Math.max(t, oy), window.innerHeight - 70);
            }
            dragTarget.style.left=l+'px'; dragTarget.style.top=t+'px';
            // Highlight folder under cursor (only when dragging an app/game/file)
            let dt = dragTarget.getAttribute('data-type');
            document.querySelectorAll('.desktop-icon.folder-drop-target').forEach(el=>el.classList.remove('folder-drop-target'));
            document.querySelectorAll('.desktop-icon.swap-target').forEach(el=>el.classList.remove('swap-target'));
            if(dt==='app' || dt==='game' || dt==='file') {
                dragTarget.style.pointerEvents='none';
                let elBelow = document.elementFromPoint(e.clientX, e.clientY);
                dragTarget.style.pointerEvents='';
                let folderIcon = elBelow && elBelow.closest('.desktop-icon[data-type="folder"]');
                if(folderIcon && folderIcon !== dragTarget) {
                    folderIcon.classList.add('folder-drop-target');
                } else if(iconDragMode === 'grid') {
                    // Highlight icon that will be swapped
                    const gs = iconSpacing;
                    const allIcons = Array.from(desktopIconsContainer.querySelectorAll('.desktop-icon'));
                    const occupant = allIcons.find(ic => {
                        if(ic === dragTarget) return false;
                        const il = parseFloat(ic.style.left), it = parseFloat(ic.style.top);
                        return Math.abs(il - l) < gs * 0.5 && Math.abs(it - t) < gs * 0.5;
                    });
                    if(occupant) occupant.classList.add('swap-target');
                }
            }
        }
    }
    function stopDrag(e) {
        if(!dragTarget) return;
        dragTarget.classList.remove('dragging');
        document.querySelectorAll('.desktop-icon.folder-drop-target').forEach(el=>el.classList.remove('folder-drop-target'));
        document.querySelectorAll('.desktop-icon.swap-target').forEach(el=>el.classList.remove('swap-target'));
        let type=dragTarget.getAttribute('data-type'), id=dragTarget.getAttribute('data-id');
        // Resolve element under cursor while ignoring the dragged item itself
        dragTarget.style.pointerEvents='none';
        let under = document.elementFromPoint(e.clientX,e.clientY);
        dragTarget.style.pointerEvents='';
        let recycle = under && under.closest('.desktop-icon[data-id="recycleBin"]');
        let folderIcon = under && under.closest('.desktop-icon[data-type="folder"]');
        // Drop on Recycle Bin
        if(recycle && (type==='app'||type==='file'||type==='game')) {
            if(type==='app' && !deletedApps.includes(id)) { deletedApps.push(id); }
            else if(type==='file') { desktopFiles=desktopFiles.filter(f=>f.id!=id); }
            else if(type==='game') { uninstallGame(id); }
            renderDesktopIcons();
            if(openWindows.has('recycleBin')) refreshRecycleBin();
            // Refresh file explorer if it's on the Desktop or Recycle Bin path
            const fxWin = openWindows.get('fileExplorer');
            if(fxWin) { const fxPath = fxWin.windowElement.querySelector('#fxPath'); if(fxPath && (fxPath.textContent.includes('Desktop') || fxPath.textContent.includes('Recycle'))) { /* trigger re-render via click */ } }
            dragTarget=null;
            document.removeEventListener('mousemove',onDragMove);
            document.removeEventListener('mouseup',stopDrag);
            saveState();
            return;
        }
        // Drop on a folder -> add to folder.contents
        if(folderIcon && folderIcon !== dragTarget && (type==='app'||type==='game'||type==='file')) {
            let folderId = folderIcon.getAttribute('data-id');
            let folder = customFolders.find(f=>String(f.id)===String(folderId));
            if(folder) {
                folder.contents = folder.contents || [];
                let key = type==='game' ? `game_${id}` : (type==='file' ? `file_${id}` : id);
                if(!folder.contents.includes(key) && !folder.contents.includes(String(key))) folder.contents.push(key);
                // Little "absorb" animation on the folder icon
                folderIcon.animate(
                    [{transform:'scale(1)'},{transform:'scale(1.18)'},{transform:'scale(1)'}],
                    {duration:260, easing:'ease-out'}
                );
                renderDesktopIcons();
                if(openWindows.has(`folder_${folderId}`)) { openWindows.get(`folder_${folderId}`).windowElement.remove(); openWindows.delete(`folder_${folderId}`); openFolder(folderId); }
                dragTarget=null;
                document.removeEventListener('mousemove',onDragMove);
                document.removeEventListener('mouseup',stopDrag);
                saveState();
                return;
            }
        }
        if(isDraggingForMove) {
            let l=parseFloat(dragTarget.style.left), t=parseFloat(dragTarget.style.top);
            if(iconDragMode === 'grid') {
                const gs = iconSpacing, ox = 20, oy = 20;
                l = ox + Math.round((l - ox) / gs) * gs;
                t = oy + Math.round((t - oy) / gs) * gs;
                l = Math.min(Math.max(l, ox), window.innerWidth - dragTarget.offsetWidth);
                t = Math.min(Math.max(t, oy), window.innerHeight - 70);
                dragTarget.style.left = l + 'px';
                dragTarget.style.top = t + 'px';

                // Check for collision with another icon and swap them
                const snapOrig = (v, gs, o) => o + Math.round((v - o) / gs) * gs;
                const origL = snapOrig(dragOrigLeft, gs, ox);
                const origT = snapOrig(dragOrigTop, gs, oy);
                const allIcons = Array.from(desktopIconsContainer.querySelectorAll('.desktop-icon'));
                const occupant = allIcons.find(ic => {
                    if(ic === dragTarget) return false;
                    const il = parseFloat(ic.style.left), it = parseFloat(ic.style.top);
                    return Math.abs(il - l) < gs * 0.5 && Math.abs(it - t) < gs * 0.5;
                });
                if(occupant) {
                    // Swap: move occupant to dragged icon's original snapped position
                    occupant.style.left = origL + 'px';
                    occupant.style.top = origT + 'px';
                    // Animate the swap
                    occupant.animate([{transform:'scale(0.85)'},{transform:'scale(1)'}], {duration:200, easing:'ease-out'});
                    // Update occupant's stored position
                    const oType = occupant.getAttribute('data-type');
                    const oId = occupant.getAttribute('data-id');
                    if(oType==='app') appPositions[oId]={x:origL,y:origT};
                    else if(oType==='folder') { let f=customFolders.find(f=>f.id==oId); if(f){f.x=origL;f.y=origT;} }
                    else if(oType==='file') { let f=desktopFiles.find(f=>f.id==oId); if(f){f.x=origL;f.y=origT;} }
                    else if(oType==='game') appPositions[`game_${oId}`]={x:origL,y:origT};
                }
            }
            if(type==='app') appPositions[id]={x:l,y:t};
            else if(type==='folder') { let f=customFolders.find(f=>f.id==id); if(f) { f.x=l; f.y=t; } }
            else if(type==='file') { let f=desktopFiles.find(f=>f.id==id); if(f) { f.x=l; f.y=t; } }
            else if(type==='game') appPositions[`game_${id}`]={x:l,y:t};
            saveState();
        }
        dragTarget=null;
        document.removeEventListener('mousemove',onDragMove);
        document.removeEventListener('mouseup',stopDrag);
    }
    function applyDesktopSettings() { 
        document.querySelectorAll('.desktop-icon').forEach(ic=>{ 
            ic.style.width=iconSize+'px'; 
            ic.querySelector('span').style.fontSize=fontSize+'px'; 
            ic.style.background = `rgba(0,0,0,${iconLabelTransparency})`; 
            ic.style.backdropFilter = 'none'; 
            ic.querySelector('span').style.display = showIconLabels ? 'block' : 'none';
        }); 
        if(!wallpaperUrl && !wallpaperDataURL) desktopDiv.style.backgroundColor=desktopBgColor; 
        if(taskbarAutoHide) taskbar.classList.add('auto-hide'); else taskbar.classList.remove('auto-hide'); 
        taskbar.style.height=taskbarHeight+'px'; 
        document.querySelectorAll('.app-window').forEach(w=>{ 
            w.style.borderRadius=borderRadius+'px'; 
            let h=w.querySelector('.window-header'); 
            if(h) h.style.borderRadius=`${borderRadius}px ${borderRadius}px 0 0`; 
            w.style.opacity = windowOpacity; 
        }); 
        applyAccentAndTaskbar(); 
        saveState(); 
    }
    function openFolder(id) {
        let f = customFolders.find(f=>String(f.id)===String(id));
        if(!f) return;
        if(openWindows.has(`folder_${id}`)) { const _fw=openWindows.get(`folder_${id}`).windowElement; _fw.style.display='flex'; _fw.style.zIndex=Date.now(); return; }
        let items = (f.contents||[]).map(key => {
            let k = String(key);
            if(k.startsWith('game_')) {
                let gid = k.slice(5);
                let g = downloadedGames.find(g=>String(g.id)===gid);
                if(!g) return null;
                return { kind:'game', key:k, id:gid, name:g.name, icon:g.icon };
            }
            if(k.startsWith('file_')) {
                let fid = k.slice(5);
                let df = desktopFiles.find(df=>String(df.id)===fid);
                if(!df) return null;
                return { kind:'file', key:k, id:fid, name:df.name, icon:'📄' };
            }
            let a = APP_LIST.find(a=>String(a.id)===k);
            if(!a) return null;
            return { kind:'app', key:k, id:a.id, name:a.name, icon: customAppIcons[a.id] || a.icon };
        }).filter(Boolean);
        let body;
        if(items.length === 0) {
            body = `<div class="folder-grid-empty">📁 This folder is empty.<br><br>Drag any app, game, or file from the desktop onto the folder icon to add it here.</div>`;
        } else {
            body = '<div class="folder-grid">' + items.map(it => {
                let iconHtml = (typeof it.icon === 'string' && it.icon.startsWith('http'))
                    ? `<img src="${it.icon}" alt="">`
                    : `<div class="folder-item-icon-emoji">${it.icon}</div>`;
                return `<div class="folder-item" data-kind="${it.kind}" data-key="${it.key}" data-id="${it.id}" title="Double-click to open">
                    <button class="folder-remove" data-remove="${it.key}" title="Remove from folder">×</button>
                    ${iconHtml}
                    <span class="label">${escapeHtml(it.name)}</span>
                </div>`;
            }).join('') + '</div>';
        }
        let win = createWindow(`📁 ${f.name}`, body, `folder_${id}`);
        document.body.appendChild(win); win.style.zIndex = Date.now();
        win.style.zIndex = Date.now();
        // Wire up item interactions
        win.querySelectorAll('.folder-item').forEach(el => {
            el.addEventListener('dblclick', () => {
                let kind = el.getAttribute('data-kind');
                let itemId = el.getAttribute('data-id');
                if(kind==='app') launchApp(itemId);
                else if(kind==='game') { let g=downloadedGames.find(g=>String(g.id)===itemId); if(g&&g.launch) g.launch(); }
                else if(kind==='file') openFile(itemId);
            });
        });
        win.querySelectorAll('.folder-remove').forEach(btn => {
            btn.addEventListener('click', (ev) => {
                ev.stopPropagation();
                let key = btn.getAttribute('data-remove');
                f.contents = (f.contents||[]).filter(x => String(x) !== String(key));
                // Make sure the item gets a fresh desktop position if needed
                if(key.startsWith('game_')) { let gid=key.slice(5); if(!appPositions[`game_${gid}`]) appPositions[`game_${gid}`]=getNextFreePosition(); }
                else if(!key.startsWith('file_')) { if(!appPositions[key]) appPositions[key]=getNextFreePosition(); }
                renderDesktopIcons();
                // Re-open the folder window with refreshed content
                if(openWindows.has(`folder_${id}`)) { openWindows.get(`folder_${id}`).windowElement.remove(); openWindows.delete(`folder_${id}`); }
                openFolder(id);
                saveState();
            });
        });
    }
    function openFile(id) { let f=desktopFiles.find(f=>f.id==id); if(!f) return; let win=createWindow(f.name,`<pre>${escapeHtml(f.content)}</pre><button id="delFile">Delete</button>`, `file_${id}`); document.body.appendChild(win); win.style.zIndex = Date.now(); win.querySelector('#delFile').onclick=()=>{ desktopFiles=desktopFiles.filter(x=>x.id!=id); win.remove(); renderDesktopIcons(); saveState(); }; }
    function createNewFolder() { let id=Date.now()+Math.random(); let name="New Folder"; let c=1; while(customFolders.some(f=>f.name===name)) name=`New Folder (${c++})`; let p=getNextFreePosition(); customFolders.push({id,name,x:p.x,y:p.y,contents:[]}); renderDesktopIcons(); saveState(); }
    function removeFolder(id) { let idx=customFolders.findIndex(f=>f.id==id); if(idx!==-1) customFolders.splice(idx,1); if(openWindows.has(`folder_${id}`)) openWindows.get(`folder_${id}`).windowElement.remove(); renderDesktopIcons(); saveState(); }
    function refreshRecycleBin() { 
        let w=openWindows.get('recycleBin'); 
        if(w) { 
            let c=w.windowElement.querySelector('.window-content'); 
            if(c) { 
                const rb = vfsResolve('C:\\Recycle Bin');
                const vfsItems = rb ? rb.children : [];
                const allEmpty = deletedApps.length===0 && vfsItems.length===0;
                if(allEmpty) { 
                    c.innerHTML='<div style="text-align:center;padding:40px;color:#888;">🗑️<br><br>Recycle Bin is empty</div>'; 
                } else { 
                    let h='<div style="padding:8px;">';
                    // Deleted apps
                    if(deletedApps.length>0) {
                        h+='<div style="font-size:11px;color:#888;font-weight:600;text-transform:uppercase;padding:4px 0 8px;">Desktop Apps</div>';
                        deletedApps.forEach(aid=>{ 
                            let a=APP_LIST.find(a=>a.id==aid); 
                            if(a) { 
                                const icoHtml = a.icon && a.icon.startsWith('http') ? `<img src="${a.icon}" style="width:20px;height:20px;object-fit:contain;vertical-align:middle;">` : a.icon;
                                h+=`<div style="display:flex;align-items:center;gap:10px;padding:6px 8px;border-radius:4px;cursor:pointer;margin-bottom:2px;" onmouseover="this.style.background='rgba(0,0,0,0.05)'" onmouseout="this.style.background=''">${icoHtml} <span style="flex:1;font-size:13px;">${a.name}</span> <button data-restore="${aid}" style="font-size:11px;padding:3px 8px;border:1px solid #ccc;border-radius:4px;background:white;cursor:pointer;">Restore</button></div>`; 
                            }
                        }); 
                    }
                    // VFS deleted files
                    if(vfsItems.length>0) {
                        h+=`<div style="font-size:11px;color:#888;font-weight:600;text-transform:uppercase;padding:${deletedApps.length?'12px':'4px'} 0 8px;">Deleted Files</div>`;
                        vfsItems.forEach(item => {
                            const ico = item.type === 'folder' ? '📁' : '📄';
                            h+=`<div style="display:flex;align-items:center;gap:10px;padding:6px 8px;border-radius:4px;margin-bottom:2px;">${ico} <span style="flex:1;font-size:13px;">${item.name}</span> <button data-vfs-restore="${item.name}" style="font-size:11px;padding:3px 8px;border:1px solid #ccc;border-radius:4px;background:white;cursor:pointer;">Restore</button></div>`;
                        });
                    }
                    h+=`<div style="margin-top:12px;padding-top:8px;border-top:1px solid #eee;"><button id="rbEmptyAll" style="color:#c00;border:1px solid #faa;padding:5px 14px;border-radius:4px;background:#fff;cursor:pointer;font-size:12px;">🗑️ Empty Recycle Bin</button></div>`;
                    h+='</div>';
                    c.innerHTML=h; 
                    c.querySelectorAll('[data-restore]').forEach(btn=>{ 
                        btn.onclick=()=>{ let rid=btn.getAttribute('data-restore'); deletedApps=deletedApps.filter(x=>x!=rid); renderDesktopIcons(); refreshRecycleBin(); saveState(); }; 
                    }); 
                    c.querySelectorAll('[data-vfs-restore]').forEach(btn => {
                        btn.onclick = () => { vfsRestore(btn.getAttribute('data-vfs-restore')); refreshRecycleBin(); };
                    });
                    const emptyBtn = c.querySelector('#rbEmptyAll');
                    if(emptyBtn) emptyBtn.onclick = () => {
                        if(confirm('Permanently delete all items?')) {
                            vfsEmptyRecycle(); deletedApps=[]; renderDesktopIcons(); refreshRecycleBin(); saveState();
                        }
                    };
                } 
            } 
        } 
    }
    function restoreAllApps() { if(deletedApps.length===0) return; deletedApps.forEach(appId=>{ if(!appPositions[appId]) appPositions[appId]=getNextFreePosition(); }); deletedApps=[]; renderDesktopIcons(); if(openWindows.has('recycleBin')) refreshRecycleBin(); saveState(); alert("All apps restored from Recycle Bin."); }
    function uninstallGame(gid) { downloadedGames = downloadedGames.filter(g => g.id != gid); deletedDownloadedGames.push(gid); renderDesktopIcons(); saveState(); }

