    // --- PINTEREST APP ---
    function openPinterestApp() {
        const win = createWindow("Pinterest - Wallpaper Gallery", `
            <div style="padding:10px;">
                <h3>📌 Pinterest Wallpapers</h3>
                <div id="pinterestGallery" class="pinterest-gallery"></div>
                <p style="margin-top:10px; font-size:12px;">Right-click any image → Set as desktop wallpaper</p>
            </div>
        `, "pinterestApp");
        document.body.appendChild(win); win.style.zIndex = Date.now();
        win.style.zIndex = Date.now();
        const galleryDiv = win.querySelector('#pinterestGallery');
        const imageIds = Array.from({length: 20}, () => Math.floor(Math.random() * 200) + 1);
        imageIds.forEach(id => {
            const imgUrl = `https://picsum.photos/id/${id}/300/200`;
            const fullUrl = `https://picsum.photos/id/${id}/1920/1080`;
            const img = document.createElement('img');
            img.src = imgUrl; img.className = 'pinterest-img'; img.title = `Image ${id}`;
            img.addEventListener('click', (e) => { e.stopPropagation(); openInAppBrowser(fullUrl, 'Pinterest Image'); });
            img.addEventListener('contextmenu', (e) => {
                e.preventDefault();
                if (confirm("Set this image as your desktop wallpaper?")) {
                    wallpaperUrl = fullUrl; wallpaperDataURL = null; applyWallpaper(); saveState(); alert("Wallpaper updated!");
                }
            });
            galleryDiv.appendChild(img);
        });
    }

