        const wallpaperUpload = win.querySelector('#wallpaperUpload');
        if (wallpaperUpload) wallpaperUpload.addEventListener('change', (e) => {
            const file = e.target.files[0]; if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => { wallpaperUrl = null; wallpaperDataURL = ev.target.result; applyWallpaper(); saveState(); };
            reader.readAsDataURL(file);
        });
        const resetWallpaper = win.querySelector('#resetWallpaper');
        if (resetWallpaper) resetWallpaper.onclick = () => { wallpaperUrl = null; wallpaperDataURL = null; applyWallpaper(); saveState(); };

