        document.getElementById('ctxSmallIcons').onclick = () => { iconSize = Math.max(iconSize-10,50); applyDesktopSettings(); if(activeContextMenu) activeContextMenu.remove(); activeContextMenu=null; };
        document.getElementById('ctxRefreshAll').onclick = () => { renderDesktopIcons(); if(activeContextMenu) activeContextMenu.remove(); activeContextMenu=null; };
