                    { name: 'Its Flat Friday.mp3', artist: 'Various Artists', url: 'https://raw.githubusercontent.com/krisxxxllkrisipurvanov-cpu/Windows-Server-2026/main/its-flat-fuck-friday-you-fucking-losers.mp3' }
