                                m.innerHTML = `<div class="ctx-item" id="rbRestore"><span class="ctx-icon"><svg viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M14 8A6 6 0 0 1 2.17 10M2 8a6 6 0 0 1 11.83-2" stroke="white" stroke-width="1.4" stroke-linecap="round"/><path d="M2 10.5V8h2.5" stroke="white" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg></span>Restore</div><div class="ctx-sep"></div><div class="ctx-item danger" id="rbDelete"><span class="ctx-icon"><svg viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5.5 1.5A1.5 1.5 0 0 1 7 0h2a1.5 1.5 0 0 1 1.5 1.5H13a.5.5 0 0 1 0 1h-.5l-.845 9.832A1.5 1.5 0 0 1 10.16 14H5.842a1.5 1.5 0 0 1-1.494-1.37L3.5 2.5H3a.5.5 0 0 1 0-1h2.5z" fill="currentColor"/></svg></span>Delete permanently</div>`;
                                document.body.appendChild(m);
